{"cpp.json":"{
	// Place your snippets for cpp here. Each snippet is defined under a snippet name and has a prefix, body and
	// description. The prefix is what is used to trigger the snippet and the body will be expanded and inserted. Possible variables are:
	// $1, $2 for tab stops, $0 for the final cursor position, and ${1:label}, ${2:another} for placeholders. Placeholders with the
	// same ids are connected.
	// Example:
	// "Print to console": {
	// 	"prefix": "log",
	// 	"body": [
	// 		"console.log('$1');",
	// 		"$2"
	// 	],
	// 	"description": "Log output to console"
	// }
	"For Loop": {
		"prefix": ["for"],
		"body": ["for(${1:int} ${2:i}=${3:0}; ${2:i}<${4:n}; ++${2:i}) {", "\t$0", "}"],
		"description": "A for loop."
	},
	"Reverse For Loop": {
		"prefix": ["forr"],
		"body": ["for(${1:int} ${2:i}=${3:n}-1; ${2:i}>=${4:0}; --${2:i}) {", "\t$0", "}"],
		"description": "A reverse for loop."
	},
	"Foreach Loop": {
		"prefix": ["fore"],
		"body": ["for(auto &${1:x}: ${2:collection}) {", "\t$0", "}"],
		"description": "A for each loop."
	},
	"If statement": {
		"prefix": ["if"],
		"body": ["if(${1:condition}) {", "\t$0", "}"],
		"description": "An if statement."
	},
	"Elif statement": {
		"prefix": ["elif"],
		"body": ["elif(${1:condition}) {", "\t$0", "}"],
		"description": "An if statement."
	},
	"boilerplate": {
		"prefix": ["boilerplate"],
		"body": ["#include <iostream>", "", "", "using namespace std;", "", "", "int main() {", "\t${1://code}", "", "\treturn 0;", "}"]
	}
}"}
